  1	package hotel.reservations;
  2	
  3	import hotel.documents.DocumentTexts;
  4	import hotel.documents.ReservationReceipt;
  5	import hotel.messages.EmailSender;
  6	import hotel.rooms.Room;
  7	import hotel.rooms.Rooms;
  8	import java.math.BigDecimal;
  9	
 10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 11	public final class ReservationService {
 12	
 13	    static final String HOTEL_NAME = "Pousada Maré Alta";
 14	
 15	    private final Rooms rooms;
 16	    private final ReservationStore store;
 17	    private final PriceCalculator priceCalculator;
 18	    private final EmailSender emailSender;
 19	
 20	    public ReservationService(
 21	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 22	        this.rooms = rooms;
 23	        this.store = store;
 24	        this.priceCalculator = priceCalculator;
 25	        this.emailSender = emailSender;
 26	    }
 27	
 28	    public synchronized Reservation create(NewReservation request) {
 29	        if (!request.checkOut().isAfter(request.checkIn())) {
 30	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 31	        }
 32	        if (request.guests() < 1) {
 33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 34	        }
 35	        Room room = rooms.find(request.roomNumber())
 36	                .orElseThrow(() -> new HotelException(
 37	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 38	        if (request.guests() > room.capacity()) {
 39	            throw new HotelException(
 40	                    ErrorCode.CAPACITY_EXCEEDED,
 41	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 42	        }
 43	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 44	            throw new HotelException(
 45	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 46	        }
 47	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 48	        return store.add(request, price);
 49	    }
 50	
 51	    public Reservation find(long reservationId) {
 52	        return store.find(reservationId)
 53	                .orElseThrow(() -> new HotelException(
 54	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 55	    }
 56	
 57	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 58	    public synchronized Reservation confirm(long reservationId) {
 59	        Reservation reservation = find(reservationId);
 60	        if (reservation.status() != ReservationStatus.PENDING) {
 61	            throw notAllowed(reservation, "confirm");
 62	        }
 63	        reservation.confirmPayment();
 64	        store.update(reservation);
 65	        Room room = roomOf(reservation);
 66	        ReservationReceipt receipt;
 67	        if (reservation.guest().isCompany()) {
 68	            receipt = new ReservationReceipt("Fatura de hospedagem", reservation, room,
 69	                    DocumentTexts.companyInvoice(reservation, room));
 70	        } else if (reservation.guest().isForeigner()) {
 71	            receipt = new ReservationReceipt("Booking receipt", reservation, room,
 72	                    DocumentTexts.foreignReceipt(reservation, room));
 73	        } else {
 74	            receipt = new ReservationReceipt("Comprovante de reserva", reservation, room,
 75	                    DocumentTexts.personReceipt(reservation, room));
 76	        }
 77	        emailSender.send(
 78	                reservation.guest().email(),
 79	                "Reserva confirmada - " + HOTEL_NAME,
 80	                confirmationEmailBody(reservation, receipt));
 81	        return reservation;
 82	    }
 83	
 84	    /**
 85	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 86	     * reservation was never paid, so nothing comes back).
 87	     */
 88	    public synchronized Reservation cancel(long reservationId) {
 89	        Reservation reservation = find(reservationId);
 90	        if (reservation.status() != ReservationStatus.PENDING
 91	                && reservation.status() != ReservationStatus.CONFIRMED) {
 92	            throw notAllowed(reservation, "cancel");
 93	        }
 94	        BigDecimal refund = switch (reservation.ratePlan()) {
 95	            case STANDARD -> reservation.amountPaid();
 96	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 97	        };
 98	        reservation.cancel(refund);
 99	        store.update(reservation);
100	        return reservation;
101	    }
102	
103	    public synchronized Reservation checkIn(long reservationId) {
104	        Reservation reservation = find(reservationId);
105	        if (reservation.status() != ReservationStatus.CONFIRMED) {
106	            throw notAllowed(reservation, "check in");
107	        }
108	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
109	        store.update(reservation);
110	        return reservation;
111	    }
112	
113	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
114	    public synchronized ReservationReceipt checkOut(long reservationId) {
115	        Reservation reservation = find(reservationId);
116	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
117	            throw notAllowed(reservation, "check out");
118	        }
119	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
120	        store.update(reservation);
121	        Room room = roomOf(reservation);
122	        ReservationReceipt finalReceipt;
123	        if (reservation.guest().isCompany()) {
124	            finalReceipt = new ReservationReceipt("Fatura de hospedagem", reservation, room,
125	                    DocumentTexts.companyInvoice(reservation, room));
126	        } else if (reservation.guest().isForeigner()) {
127	            finalReceipt = new ReservationReceipt("Booking receipt", reservation, room,
128	                    DocumentTexts.foreignReceipt(reservation, room));
129	        } else {
130	            finalReceipt = new ReservationReceipt("Comprovante de reserva", reservation, room,
131	                    DocumentTexts.personReceipt(reservation, room));
132	        }
133	        return finalReceipt;
134	    }
135	
136	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
137	    public ReservationReceipt receiptCopy(long reservationId) {
138	        Reservation reservation = find(reservationId);
139	        if (!reservation.isPaid()) {
140	            throw notAllowed(reservation, "issue a receipt for");
141	        }
142	        Room room = roomOf(reservation);
143	        ReservationReceipt copy;
144	        if (reservation.guest().isCompany()) {
145	            copy = new ReservationReceipt("Fatura de hospedagem", reservation, room,
146	                    DocumentTexts.companyInvoice(reservation, room));
147	        } else if (reservation.guest().isForeigner()) {
148	            copy = new ReservationReceipt("Booking receipt", reservation, room,
149	                    DocumentTexts.foreignReceipt(reservation, room));
150	        } else {
151	            copy = new ReservationReceipt("Comprovante de reserva", reservation, room,
152	                    DocumentTexts.personReceipt(reservation, room));
153	        }
154	        return copy;
155	    }
156	
157	    private Room roomOf(Reservation reservation) {
158	        return rooms.find(reservation.roomNumber()).orElseThrow();
159	    }
160	
161	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
162	        return "Olá, " + reservation.guest().name() + "!\n\n"
163	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
164	                + receipt.text() + "\n"
165	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
166	                + "Até breve!\n";
167	    }
168	
169	    private static HotelException notAllowed(Reservation reservation, String operation) {
170	        return new HotelException(
171	                ErrorCode.OPERATION_NOT_ALLOWED,
172	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
173	    }
174	}
  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.LocalDate;
  7	import java.time.Month;
  8	
  9	/**
 10	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 11	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 12	 * (half-even) at every step.
 13	 */
 14	public final class PriceCalculator {
 15	
 16	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 17	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 18	
 19	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 20	        int nights = 0;
 21	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 22	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 23	            subtotal = subtotal.add(nightPrice(room, night));
 24	            nights++;
 25	        }
 26	        BigDecimal discount = switch (ratePlan) {
 27	            case STANDARD -> cents(BigDecimal.ZERO);
 28	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 29	        };
 30	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 31	    }
 32	
 33	    BigDecimal nightPrice(Room room, LocalDate night) {
 34	        BigDecimal nightlyRate = room.nightlyRate();
 35	        if (isHighSeason(night)) {
 36	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 37	        }
 38	        return cents(nightlyRate);
 39	    }
 40	
 41	    /** High season: from December 15 to the end of February, and the whole of July. */
 42	    static boolean isHighSeason(LocalDate date) {
 43	        Month month = date.getMonth();
 44	        return month == Month.JANUARY
 45	                || month == Month.FEBRUARY
 46	                || month == Month.JULY
 47	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
 48	    }
 49	
 50	    static BigDecimal cents(BigDecimal value) {
 51	        return value.setScale(2, RoundingMode.HALF_EVEN);
 52	    }
 53	}
 54	package hotel.documents;
 55	
 56	import java.math.BigDecimal;
 57	import java.time.LocalDate;
 58	import java.time.format.DateTimeFormatter;
 59	import java.util.Locale;
 60	
 61	/** How money and dates are written in the texts the guest reads (Brazilian Portuguese). */
 62	public final class TextFormat {
 63	
 64	    private static final Locale BRAZIL = Locale.forLanguageTag("pt-BR");
 65	    private static final DateTimeFormatter BRAZILIAN_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");
 66	
 67	    private TextFormat() {
 68	    }
 69	
 70	    public static String money(BigDecimal amount) {
 71	        return "R$ " + String.format(BRAZIL, "%,.2f", amount);
 72	    }
 73	
 74	    public static String date(LocalDate date) {
 75	        return BRAZILIAN_DATE.format(date);
 76	    }
 77	}

